import Foundation
import Testing
@testable import LooperCore

/// Test media generated by `scripts/make-test-clip.sh`.
///
/// Fixtures live in `$LOOPER_FIXTURES`, or `<repo>/fixtures` by default. Tests that
/// need them are skipped when they are missing, except in CI, where
/// `LOOPER_REQUIRE_FIXTURES=1` turns a missing fixture into a failure.
enum Fixtures {
    static let directory: URL = {
        if let path = ProcessInfo.processInfo.environment["LOOPER_FIXTURES"], !path.isEmpty {
            return URL(fileURLWithPath: path, isDirectory: true)
        }
        // This file is <repo>/LooperCore/Tests/LooperCoreTests/Support/Fixtures.swift.
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 { url.deleteLastPathComponent() }
        return url.appendingPathComponent("fixtures", isDirectory: true)
    }()

    static var available: Bool {
        (VideoFixture.all.map(\.url) + AudioFixture.all.map(\.url))
            .allSatisfy { FileManager.default.fileExists(atPath: $0.path) }
    }

    static var required: Bool {
        ProcessInfo.processInfo.environment["LOOPER_REQUIRE_FIXTURES"] == "1"
    }

    static func url(_ relativePath: String) -> URL {
        directory.appendingPathComponent(relativePath)
    }
}

/// A generated loop clip. Values must match `scripts/make-test-clip.sh`.
struct VideoFixture: Sendable, CustomTestStringConvertible {
    let name: String
    let width: Int
    let height: Int
    /// Frame duration as a rational, e.g. 1/30 or 1001/30000.
    let frameDurationValue: Int64
    let frameDurationTimescale: Int32
    let frameCount: Int
    /// Side of each square block in the binary frame-index strip.
    let bitBlock: Int
    let hasAudio: Bool

    var url: URL { Fixtures.url(name) }
    var testDescription: String { name }
    var framesPerSecond: Double { Double(frameDurationTimescale) / Double(frameDurationValue) }

    static let main = VideoFixture(
        name: "loop-1080p30.mp4", width: 1920, height: 1080,
        frameDurationValue: 1, frameDurationTimescale: 30, frameCount: 900, bitBlock: 48, hasAudio: false)
    /// Small and low bitrate: for long (8 h) export tests.
    static let tiny = VideoFixture(
        name: "loop-tiny30.mp4", width: 320, height: 180,
        frameDurationValue: 1, frameDurationTimescale: 30, frameCount: 900, bitBlock: 16, hasAudio: false)
    static let fps24 = VideoFixture(
        name: "loop-360p24.mp4", width: 640, height: 360,
        frameDurationValue: 1, frameDurationTimescale: 24, frameCount: 720, bitBlock: 16, hasAudio: false)
    /// 29.97 fps (30000/1001): where floating-point time math would drift.
    static let fps2997 = VideoFixture(
        name: "loop-360p2997.mp4", width: 640, height: 360,
        frameDurationValue: 1001, frameDurationTimescale: 30000, frameCount: 900, bitBlock: 16, hasAudio: false)
    /// Has a stereo AAC track (440 Hz left, 660 Hz right).
    static let withAudio = VideoFixture(
        name: "loop-360p30-audio.mp4", width: 640, height: 360,
        frameDurationValue: 1, frameDurationTimescale: 30, frameCount: 900, bitBlock: 16, hasAudio: true)

    static let all: [VideoFixture] = [main, tiny, fps24, fps2997, withAudio]
}

/// A generated audio file: 48 kHz stereo.
struct AudioFixture: Sendable, CustomTestStringConvertible {
    let path: String
    let seconds: Double

    var url: URL { Fixtures.url(path) }
    var testDescription: String { path }

    /// 10 s of pink noise, the ambient bed.
    static let bed = AudioFixture(path: "audio/bed.wav", seconds: 10)
    /// The playlist folder, one tone per lossless format.
    static let playlistDirectory = "audio/playlist"
    static let playlist: [AudioFixture] = [
        AudioFixture(path: "audio/playlist/01-tone-220.wav", seconds: 6),
        AudioFixture(path: "audio/playlist/02-tone-330.aiff", seconds: 6),
        AudioFixture(path: "audio/playlist/03-tone-440.flac", seconds: 6),
    ]

    /// A video with sound, like a screen recording of a sound website: 1 s silence,
    /// 8.5 s pink noise, 0.5 s silence (AAC), over a plain picture.
    static let recording = AudioFixture(path: "audio/recording.mp4", seconds: 10)
    static let recordingSound = AudioTrim(start: 1, end: 9.5)

    static let all: [AudioFixture] = [bed, recording] + playlist
}
